'use strict';
(()=>{const $=s=>document.querySelector(s),D=RPG_DATA,bridge=RPG_ACCOUNT_BRIDGE,esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fmt=n=>Math.ceil(Number(n)||0).toLocaleString('ko-KR');
const dialog=document.createElement('dialog');dialog.id='raid-dialog';dialog.className='raid-dialog';dialog.innerHTML='<div class="raid-shell"><header class="raid-header"><div><small>EXPEDITION RAID</small><h2>같이 레이드하기</h2></div><button id="raid-close" aria-label="레이드 창 닫기">×</button></header><div class="raid-scroll"><p id="raid-notice" class="raid-notice" role="status" aria-live="polite"></p><div id="raid-body"></div></div></div>';document.body.append(dialog);
const drawPositions=new Map();let session=null,practice=null,view='',timer=null,busy=false,notice='',intent=null,stat='damage',auto=true,closed=true,owner=null,selected=null,networkErrors=0,lastRequest=0,rescueTarget=null,anim=0,epoch=0;const image=new Image();image.src='rpg-pixels-v2/dungeons/mine.png';const render=bridge.renderer;
function say(s){notice=s;$('#raid-notice').textContent=s;}
function me(){return session?.state.players.find(p=>p.id===session.you);}
function auth(){return window.RPG_ACCOUNT_UI;}
function heroList(){const payload=auth()?.account?.remote?.payload;return payload?.heroes.map((h,i)=>({...h,id:i})).filter(h=>h.recruited)||[];}
function options(){const heroes=heroList();return heroes.map(h=>`<option value="${h.id}" ${h.id===selected?'selected':''}>${esc(D.characters[h.id].name)} · ${esc(D.characters[h.id].classes[h.cell].name)} · Lv.${h.level}</option>`).join('');}
function beginPainting(){cancelAnimationFrame(anim);function frame(){if(closed)return;if($('#raid-arena'))paint();anim=requestAnimationFrame(frame);}anim=requestAnimationFrame(frame);}
function entry(){view='entry';const api=auth(),signed=!!api?.account?.user,heroes=heroList();if(selected===null||!heroes.some(h=>h.id===selected))selected=heroes[0]?.id??null;$('#raid-body').innerHTML=`<section class="raid-banner"><small>CO-OP RAID · CHAPTER 01</small><h3>폐광의 거신</h3><p>갈라지는 지면을 피하고, 갇힌 동료를 구출하세요.<br>거신의 핵이 열리면 함께 결정타를 날릴 시간입니다.</p><div class="raid-meta"><span>2~4인 협동</span><span>제한 시간 5분</span><span>공용 부활 2회</span></div></section>${signed?`<div class="raid-hero-select"><label for="raid-hero">함께할 캐릭터 · 클라우드 저장 기준</label><select id="raid-hero" ${heroes.length?'':'disabled'}>${options()||'<option>클라우드에 저장한 캐릭터가 없어요</option>'}</select></div>`:'<p class="raid-practice">동료와의 레이드는 구글 로그인 후 이용할 수 있어요. 혼자 연습은 바로 시작할 수 있어요.</p>'}<div class="raid-entry-grid"><section class="raid-panel"><h3>동료를 초대하세요</h3><p>방을 만들면 숫자 4자리 코드가 발급돼요.<br>같은 코드를 입력한 동료와 함께 출발하세요.</p><button class="raid-primary" data-raid="create" ${signed&&heroes.length?'':'disabled'}>방 만들기</button></section><form id="raid-join" class="raid-panel"><h3>초대 코드로 참가</h3><label for="raid-code">숫자 4자리</label><input id="raid-code" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" minlength="4" autocomplete="off" placeholder="0000" required aria-label="초대 코드 숫자 4자리"><div class="raid-actions"><button type="submit" ${signed&&heroes.length?'':'disabled'}>방 참가하기</button></div></form></div><section class="raid-panel"><h3>전투 안내</h3><p>직업에 맞춘 레이드 전용 밸런스로 진행해요. 이동은 바닥을 누르거나 방향키·WASD로, 기술은 버튼 또는 1~4키로 사용할 수 있어요. 자동 기술을 켜도 위험한 바닥은 직접 피해야 해요.</p><p>실제 피해·방어·회복·구조를 기록해요. 주요 보상은 하루 3회 레이드 결정 30개. 이후에는 보상 없이 계속 도전할 수 있어요. 실패 시 횟수는 차감하지 않아요.</p><div class="raid-actions"><button data-raid="practice">혼자 연습 · 보상 없음</button>${signed?'':'<button data-raid="login">구글 계정 연결</button>'}</div></section>`;$('#raid-hero')?.addEventListener('change',e=>selected=Number(e.target.value));$('#raid-code').addEventListener('input',e=>e.target.value=e.target.value.replace(/[^0-9]/g,''));$('#raid-join').onsubmit=e=>{e.preventDefault();request('join',{code:$('#raid-code').value});};}
function portraits(){for(const canvas of dialog.querySelectorAll('canvas[data-hero]')){const h=D.characters[Number(canvas.dataset.hero)],cell=Number(canvas.dataset.cell);render.preload(h.sheet,cell).then(()=>{if(canvas.isConnected)render.draw(canvas.getContext('2d'),h.sheet,cell,35,75,66);}).catch(()=>{});}}
function lobby(){const s=session.state,host=session.host===session.you;view='lobby';$('#raid-body').innerHTML=`<div class="raid-code-card"><div><small>초대 코드 · 숫자 4자리</small><strong>${esc(session.code)}</strong></div><button data-raid="copy">코드 복사</button></div><p class="raid-help">2~4명이 모여 준비 완료를 누르면 방장이 출발할 수 있어요. 접속이 끊겨도 같은 계정으로 돌아오면 복귀해요.</p><div id="raid-roster" class="raid-roster"></div><div class="raid-actions"><button class="raid-primary" data-raid="ready">준비 완료</button>${host?'<button data-raid="start">레이드 출발</button>':''}<button data-raid="leave">방 나가기</button></div><p class="raid-help">직업별 레이드 역할: 방어 · 회복 · 근접 공격 · 원거리 공격. 캐릭터 레벨과 무기 슬롯 강화가 적용돼요.</p>`;updateLobby();}
function updateLobby(){if(!!dialog.querySelector('[data-raid=start]')!==(session.host===session.you)){lobby();return;}const s=session.state,p=me(),names={guard:'아군 보호',heal:'회복 지원',melee:'근접 공격',ranged:'원거리 공격'};const roster=$('#raid-roster');const html=Array.from({length:4},(_,i)=>{const x=s.players[i];return x?`<article class="raid-member"><canvas width="70" height="78" data-hero="${x.hero}" data-cell="${x.cell}"></canvas><strong>${esc(x.name)} ${x.id===session.host?'♛':''}</strong><small>${esc(x.job)} · ${names[x.role]}<br>Lv.${x.level}</small><span class="${x.ready?'ready':''}">${Date.now()/1000-x.seen>15?'접속 확인 중':x.ready?'✓ 준비 완료':'준비 중'}</span>${session.host===session.you&&x.id!==session.you?`<button data-raid="kick" data-target="${i}">내보내기</button>`:''}</article>`:'<article class="raid-member empty">동료를 기다리는 중</article>';}).join('');if(roster.dataset.signature!==html){roster.innerHTML=html;roster.dataset.signature=html;portraits();}dialog.querySelector('[data-raid=ready]').textContent=p.ready?'준비 취소':'준비 완료';const start=dialog.querySelector('[data-raid=start]');if(start)start.disabled=s.players.length<2||!s.players.every(x=>x.ready);}
function battle(){view='fight';$('#raid-body').innerHTML=`${session.practice?'<p class="raid-practice">혼자 연습 · 동료 3명은 연습용 NPC예요. 기록과 보상은 저장되지 않아요.</p>':''}<div class="raid-boss-meta"><strong>폐광의 거신</strong><span id="raid-time"></span></div><div class="raid-bossbar"><i id="raid-boss-hp"></i></div><div id="raid-pattern" class="raid-pattern" aria-live="polite"></div><div class="raid-battle"><canvas id="raid-arena" width="800" height="500" aria-label="레이드 전투장. 바닥을 누르면 이동합니다."></canvas></div><p class="raid-keyhelp">바닥 터치로 이동 · 방향키/WASD · 1~4 스킬</p><div id="raid-player-bars" class="raid-player-bars"></div><div id="raid-controls" class="raid-controls"></div><div class="raid-actions"><button data-raid="auto">자동 기술 켜짐</button><button data-raid="revive">공용 부활 사용</button><button data-raid="leave">레이드 이탈</button></div><p class="raid-help">쓰러진 동료 근처에서 아래 ‘구조’ 버튼을 누르고 3초간 기다리세요. 이동하면 구조가 중단돼요.</p><div id="raid-rescue"></div>`;
$('#raid-arena').addEventListener('pointerdown',e=>{const r=e.currentTarget.getBoundingClientRect();rescueTarget=null;intent={cmd:'move',arg:{x:(e.clientX-r.left)/r.width*800,y:(e.clientY-r.top)/r.height*500}};pump();});updateBattle();beginPainting();}
function updateBattle(){const s=session.state,p=me(),b=s.boss;$('#raid-time').textContent=`${Math.floor(Math.max(0,Math.ceil(300-s.t))/60)}:${String(Math.max(0,Math.ceil(300-s.t))%60).padStart(2,'0')} · ${fmt(b.hp)} / ${fmt(b.maxHP)}`;$('#raid-boss-hp').style.width=Math.max(0,b.hp/b.maxHP*100)+'%';$('#raid-pattern').textContent=b.exposedUntil>s.t?'핵 노출! 지금 공격하면 피해 65% 증가':b.pattern==='crack'&&b.resolveAt>s.t?'균열 예고! 붉은 지면을 피하세요':s.players.some(x=>x.prison>0)?'수정 감옥! 동료를 가둔 수정을 부수세요':b.hp/b.maxHP<.25?'거신 광폭화 · 공격 속도 증가':'동료와 함께 거신을 공격하세요';$('#raid-player-bars').innerHTML=s.players.map(x=>`<div class="raid-mini"><strong>${esc(x.name)}</strong> ${x.id===p.id?'<em>나</em>':''}<progress max="${x.maxHP}" value="${x.hp}" aria-label="${esc(x.name)} 체력"></progress><span>${fmt(x.hp)} / ${fmt(x.maxHP)} ${x.prison>0?'· 수정 감옥':''}</span></div>`).join('');const controls=$('#raid-controls');if(!controls.children.length)controls.innerHTML=p.skills.map((name,i)=>`<button data-raid="skill" data-slot="${i}">${i+1}. ${esc(name)}<small></small></button>`).join('');for(const button of controls.children){const slot=Number(button.dataset.slot),cd=Math.max(0,p.cooldowns[slot]-s.t);button.disabled=cd>0||p.hp<=0||p.prison>0;button.querySelector('small').textContent=cd?Math.ceil(cd)+'초':slot===3?'궁극기 준비':'사용 가능';}dialog.querySelector('[data-raid=auto]').textContent='자동 기술 '+(auto?'켜짐':'꺼짐');dialog.querySelector('[data-raid=revive]').textContent=`공용 부활 ${s.revives}회`;dialog.querySelector('[data-raid=revive]').disabled=p.hp>0||s.revives<=0;$('#raid-rescue').innerHTML=s.players.map((x,i)=>x.id!==p.id&&x.hp<=0?`<button data-raid="rescue" data-target="${i}">${esc(x.name)} ${rescueTarget===i?'구조 중…':'구조'}</button>`:'').join('');}
function results(){view=session.state.status;cancelAnimationFrame(anim);const s=session.state;$('#raid-body').innerHTML=`<section class="raid-result-title"><small>EXPEDITION REPORT</small><h3>${s.status==='clear'?'토벌 성공':'다시 도전해요'}</h3><p>${esc(s.reason)} · ${Math.floor(s.t/60)}분 ${Math.ceil(s.t%60)}초</p></section><div class="raid-reward">${session.practice?'연습 완료 · 보상과 기록은 저장되지 않아요':s.status==='failed'?'실패 시 보상 횟수가 차감되지 않아요':session.reward?`레이드 결정 +${session.reward} · 보유 ${fmt(session.wallet)}개`:'연습·도움 참가 완료 · 주요 보상은 하루 3회예요.'}${!session.practice?`<small> · 오늘 주요 보상 ${session.daily}/3회</small>`:''}</div><div class="raid-stat-tabs">${[['damage','⚔ 피해량'],['defense','🛡 방어량'],['healing','💚 회복량']].map(([id,n])=>`<button data-raid="stat" data-stat="${id}" aria-pressed="${id===stat}">${n}</button>`).join('')}</div><div id="raid-scores"></div><div class="raid-actions">${session.practice?'<button class="raid-primary" data-raid="practice">다시 연습</button>':session.host===session.you?'<button class="raid-primary" data-raid="retry">재도전 준비</button>':'<span>방장이 재도전을 준비할 수 있어요.</span>'}<button data-raid="leave">레이드 나가기</button></div>`;scores();}
function scores(){const players=session.state.players,total=players.reduce((n,p)=>n+p[stat],0),best=players.reduce((a,p)=>p[stat]>(a?.[stat]||0)?p:a,null),title={damage:'최다 피해',defense:'수호자',healing:'치유자'};$('#raid-scores').innerHTML=[...players].sort((a,b)=>b[stat]-a[stat]).map(p=>{const share=total?p[stat]/total*100:0;return `<article class="raid-score" data-stat="${stat}"><div class="raid-score-top"><div><strong>${esc(p.name)} ${p.id===session.you?'· 나':''}</strong><small>${esc(p.job)} ${p===best&&p[stat]>0?'· '+title[stat]:''}</small></div><strong>${fmt(p[stat])} <small>${Math.ceil(share)}%</small></strong></div><div class="raid-score-bar"><i style="width:${share}%"></i></div><footer>${stat==='defense'?`자기 방어 ${fmt(p.defense-p.allyDefense)} · 아군 보호 ${fmt(p.allyDefense)}`:stat==='healing'?`자기 회복 ${fmt(p.healing-p.allyHealing)} · 아군 회복 ${fmt(p.allyHealing)}`:'실제 피해만 집계 · 초과 피해 제외'}<br>동료 구조 ${p.rescues}회 · 수정 감옥 해제 ${p.mechanics}회</footer></article>`;}).join('');for(const b of dialog.querySelectorAll('[data-raid=stat]'))b.setAttribute('aria-pressed',b.dataset.stat===stat);}
function sync(){if(!session?.room){entry();return;}if(view!==session.state.status){if(session.state.status==='lobby')lobby();else if(session.state.status==='fight')battle();else results();}else if(view==='lobby')updateLobby();else if(view==='fight')updateBattle();}
async function request(cmd,arg={}){if(busy)return;busy=true;const generation=epoch;try{let data;if(practice)data=await practice.command(cmd,arg);else{const api=auth();if(!api?.account?.user)throw Error('구글 로그인이 필요해요.');const response=await api.client.rpc('rpg_raid_command',{p_cmd:cmd,p_room:session?.room||null,p_code:arg.code||null,p_hero:selected,p_arg:arg});if(response.error)throw response.error;data=response.data;if(data?.error)throw Object.assign(Error(data.error),{code:'RAID_INPUT'});}if(generation!==epoch)return;session=data;networkErrors=0;if(notice.startsWith('연결'))say('');if(cmd==='leave'){practice=null;session=null;rescueTarget=null;view='';}sync();}catch(e){if(e.code==='42501'||/참가자를 찾지|방이 만료/.test(e.message||'')){session=null;intent=null;rescueTarget=null;view='';sync();networkErrors=0;}else if(!['P0001','RAID_INPUT'].includes(e.code))networkErrors++;say(e.code==='PGRST202'?'레이드 서버를 준비 중이에요. 잠시 후 다시 입장해 주세요.':e.message||'연결을 확인하고 다시 시도해 주세요.');}finally{busy=false;lastRequest=Date.now();}}
function chooseAuto(){const p=me(),s=session.state;if(!p||p.hp<=0||p.prison>0)return null;const slots=p.role==='heal'?[1,2,0,3]:p.role==='guard'?[2,1,0,3]:[0,1,2,3];for(const slot of slots){if(p.cooldowns[slot]>s.t)continue;if(p.role==='heal'&&[1,2].includes(slot)&&!s.players.some(x=>x.hp>0&&x.hp<x.maxHP*.82))continue;if(slot===3&&s.boss.exposedUntil<=s.t&&s.boss.hp/s.boss.maxHP>.3)continue;const support=p.role==='heal'&&[1,2].includes(slot)||p.role==='guard'&&[1,2].includes(slot);if(!support&&Math.hypot(p.x-400,p.y-190)>(['heal','ranged'].includes(p.role)?320:160))continue;return {cmd:'skill',arg:{slot}};}return null;}
async function pump(){if(closed||busy)return;if(networkErrors>=5){say('연결이 불안정해요. 자동으로 다시 연결하고 있어요. 창을 닫아도 같은 계정으로 복귀할 수 있어요.');}let action=intent;intent=null;if(!action&&session?.state.status==='fight')action=rescueTarget!==null?{cmd:'rescue',arg:{target:rescueTarget}}:auto?chooseAuto():null;await request(action?.cmd||'poll',action?.arg||{});}
function schedule(){clearInterval(timer);timer=setInterval(()=>{if(!closed&&session?.room)pump();},700);}
async function open(){if(practice){practice=null;session=null;}intent=null;rescueTarget=null;closed=false;epoch++;owner=auth()?.account?.user?.id||null;view='';notice='';if(!dialog.open)dialog.showModal();bridge.pause(true);say('');entry();beginPainting();if(owner){await request('resume');}schedule();}
function close(){closed=true;epoch++;clearInterval(timer);cancelAnimationFrame(anim);intent=null;rescueTarget=null;dialog.close();bridge.pause(false);}
$('#raid-close').onclick=close;dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('close',()=>{if(!closed)close();});
dialog.addEventListener('click',async e=>{const b=e.target.closest('[data-raid]');if(!b)return;const cmd=b.dataset.raid;if(cmd==='login'){close();auth()?.open();return;}if(cmd==='practice'){practice=new RPG_RAID_PRACTICE(selected??3,heroList().find(h=>h.id===selected)?.cell??3);session=await practice.command('poll');rescueTarget=null;view='';sync();schedule();return;}if(cmd==='auto'){auto=!auto;updateBattle();return;}if(cmd==='stat'){stat=b.dataset.stat;scores();return;}if(cmd==='copy'){try{await navigator.clipboard.writeText(session.code);say('초대 코드를 복사했어요.');}catch{say('초대 코드: '+session.code);}return;}if(cmd==='kick'){await request('kick',{target:Number(b.dataset.target)});return;}if(cmd==='rescue'){rescueTarget=Number(b.dataset.target);pump();return;}if(cmd==='skill'){intent={cmd,arg:{slot:Number(b.dataset.slot)}};pump();return;}await request(cmd);});
window.addEventListener('rpg:before-update',e=>{if(!closed&&session?.state.status==='fight'){e.preventDefault();say('새 버전이 준비됐어요. 레이드가 끝난 뒤 자동으로 반영할게요.');}});document.addEventListener('rpg:raid-open',open);document.addEventListener('rpg:account-render',()=>{if(!closed&&owner!==(auth()?.account?.user?.id||null)){session=null;practice=null;close();}});document.addEventListener('keydown',e=>{if(closed||view!=='fight'||e.target.matches('input,select,textarea'))return;const p=me();if(!p)return;const keys={ArrowLeft:[-60,0],a:[-60,0],ArrowRight:[60,0],d:[60,0],ArrowUp:[0,-60],w:[0,-60],ArrowDown:[0,60],s:[0,60]};if(keys[e.key]){e.preventDefault();const [x,y]=keys[e.key];rescueTarget=null;intent={cmd:'move',arg:{x:p.x+x,y:p.y+y}};pump();}if(/^[1-4]$/.test(e.key)){e.preventDefault();intent={cmd:'skill',arg:{slot:Number(e.key)-1}};pump();}});
function paint(){const cn=$('#raid-arena'),s=session?.state;if(!cn||!s?.boss)return;const c=cn.getContext('2d'),t=s.t+Math.min(.8,(Date.now()-lastRequest)/1000),b=s.boss;c.clearRect(0,0,800,500);c.imageSmoothingEnabled=false;if(image.complete&&image.naturalWidth){c.globalAlpha=.55;c.drawImage(image,0,0,800,500);c.globalAlpha=1;}else{c.fillStyle='#2a322a';c.fillRect(0,0,800,500);}c.fillStyle='#13261d66';c.fillRect(0,0,800,500);if(b.pattern==='crack'&&b.resolveAt>s.t){c.fillStyle='#f69b4a55';c.fillRect(b.lane-85,80,170,420);c.strokeStyle='#f4be7d';c.lineWidth=3;c.setLineDash([12,8]);c.strokeRect(b.lane-85,80,170,420);c.setLineDash([]);}if(b.exposedUntil>s.t){c.fillStyle='#d6ea95';c.shadowColor='#ffe19a';c.shadowBlur=28;c.beginPath();c.arc(400,150,24+Math.sin(t*8)*3,0,Math.PI*2);c.fill();c.shadowBlur=0;}render.draw(c,'monsters/mine.png',3,400,206,130,b.hp/b.maxHP<.25,.99,RPG_MOTION.pose(t,false,b.attackAt-2,-99,'fighter'));for(const serverP of [...s.players].sort((a,b)=>a.y-b.y)){const old=drawPositions.get(serverP.id)||serverP,p={...serverP,x:old.x+(serverP.x-old.x)*.2,y:old.y+(serverP.y-old.y)*.2};drawPositions.set(p.id,{x:p.x,y:p.y});const h=D.characters[p.hero];const motion=RPG_MOTION.pose(t,Math.hypot(p.tx-p.x,p.ty-p.y)>5,p.lastAttack,p.lastCast,h.family);render.draw(c,h.sheet,p.cell,p.x,p.y,p.hp>0?60:43,p.x>400,p.hp>0?1:.4,motion);if(p.shield>0||p.guardUntil>s.t){c.strokeStyle=p.shield>0?'#9bd7df':'#eed29b';c.lineWidth=3;c.beginPath();c.moveTo(p.x-24,p.y-8);c.lineTo(p.x-29,p.y-52);c.lineTo(p.x,p.y-70);c.lineTo(p.x+29,p.y-52);c.lineTo(p.x+24,p.y-8);c.stroke();}if(p.prison>0){c.fillStyle='#a2d6f47a';c.strokeStyle='#caf4ff';c.lineWidth=3;c.beginPath();c.moveTo(p.x,p.y-88);c.lineTo(p.x+36,p.y-40);c.lineTo(p.x+20,p.y+6);c.lineTo(p.x-24,p.y+6);c.lineTo(p.x-36,p.y-40);c.closePath();c.fill();c.stroke();}c.font='bold 13px sans-serif';c.textAlign='center';c.strokeStyle='#142219';c.lineWidth=4;c.strokeText(p.name.length>7?p.name.slice(0,7)+'…':p.name,p.x,p.y-74);c.fillStyle=p.id===session.you?'#ffdfa1':'#edf2de';c.fillText(p.name.length>7?p.name.slice(0,7)+'…':p.name,p.x,p.y-74);c.fillStyle='#10241a';c.fillRect(p.x-24,p.y+7,48,5);c.fillStyle='#b4d88e';c.fillRect(p.x-24,p.y+7,48*Math.max(0,p.hp/p.maxHP),5);}
for(const e of s.effects){const age=t-e.at;if(age<0||age>1.1)continue;const p=s.players.find(p=>p.id===e.owner);c.save();c.globalAlpha=Math.max(0,1-age/1.1);if(e.kind==='hit'||e.kind==='strike'){const family=p?D.characters[p.hero].family:'sword',ranged=['mage','archer','gunner','summoner','bard'].includes(family);c.strokeStyle=family==='mage'?'#95d7fa':family==='archer'?'#e6d5a4':family==='priest'?'#fff2b1':'#f7c88d';c.lineWidth=e.kind==='strike'?5:2;if(ranged&&p){const q=Math.min(1,age/.4),x=p.x+(400-p.x)*q,y=p.y-30+(150-p.y+30)*q;c.beginPath();c.moveTo(x-12,y+4);c.lineTo(x+10,y-4);c.stroke();}else{c.beginPath();c.moveTo(e.x-25,e.y-40);c.lineTo(e.x+25,e.y-15);c.moveTo(e.x-15,e.y-10);c.lineTo(e.x+20,e.y-42);c.stroke();}if(e.value){c.font='bold 19px monospace';c.fillStyle='#ffe8a2';c.fillText(fmt(e.value),e.x,e.y-65-age*35);}}else if(e.kind==='heal'){for(const q of s.players){c.fillStyle='#b0e6a0';c.fillRect(q.x-3,q.y-58-age*20,6,20);c.fillRect(q.x-10,q.y-51-age*20,20,6);}}else if(e.kind==='crack'){c.strokeStyle='#eebc6e';c.lineWidth=5;c.beginPath();for(let i=0;i<11;i++)c.lineTo(e.x+(i%2?30:-25),80+i*42);c.stroke();}c.restore();}}
if(new URL(location.href).searchParams.get('raid')==='practice'){open().then(()=>dialog.querySelector('[data-raid=practice]')?.click());}
})();
